def drill_into_january_order_activity(inventory):
    """
    Drill into January order activity for out-of-stock products.

    Args:
        inventory (dict): Inventory data.

    Returns:
        None
    """
    if check_out_of_stock(inventory):
        # Assuming the order activity data is stored in a separate dictionary
        order_activity = {
            "period": {
                "start_date": "2026-01-01",
                "end_date": "2026-01-31"
            },
            "orders": [
                {
                    "order_id": 1,
                    "order_date": "2026-01-05",
                    "items": [
                        {
                            "product_id": 4,
                            "quantity": 2
                        }
                    ]
                },
                {
                    "order_id": 2,
                    "order_date": "2026-01-10",
                    "items": [
                        {
                            "product_id": 1,
                            "quantity": 1
                        }
                    ]
                }
            ]
        }

        # Print the order activity for out-of-stock products
        print("January Order Activity for Out-of-Stock Products:")
        for order in order_activity["orders"]:
            for item in order["items"]:
                if item["product_id"] in [item["product_id"] for item in inventory["inventory"]["low_stock_items"]]:
                    print(f"Order ID: {order['order_id']}, Order Date: {order['order_date']}, Product ID: {item['product_id']}, Quantity: {item['quantity']}")
    else:
        print("No out-of-stock products found.")

